    @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@300;400&family=Michroma&display=swap');
    .svg-header-text {
      fill: #fff;
      font-family: var(--font-ivymode), IvyMode, 'Cormorant Garamond', Georgia, serif;
      font-size: 14px;
      letter-spacing: 0.1em;
    }
    .svg-dim-text {
      fill: #fff;
      font-family: var(--font-michroma), Michroma, sans-serif;
      font-size: 9px;
      letter-spacing: 0.05em;
    }
    .cls-1, .cls-2, .cls-3, .cls-4 {
      fill: none;
    }
    .cls-1 {
      stroke: #fff;
      stroke-width: 0.75px;
    }
    .cls-2 {
      stroke-width: .78px;
    }
    .cls-2, .cls-3 {
      stroke: #fcfafa;
      stroke-linecap: round;
      stroke-linejoin: round;
    }
    .cls-5 {
      letter-spacing: .2em;
    }
    .cls-6 {
      clip-path: url(#clippath-2);
    }
    .cls-3 {
      stroke-width: .26px;
    }
    .cls-4 {
      stroke: #fff;
      stroke-width: .25px;
    }
    .cls-7 {
      fill: #fff;
      font-family: Michroma, Michroma;
      font-size: 9px;
    }
